probs = {"доставка": 0.45, "оплата": 0.30, "возврат": 0.15, "погода": 0.07, "бегемот": 0.03}

top = sorted(probs, key=probs.get, reverse=True)[:3]
total = sum(probs[w] for w in top)
result = {w: round(probs[w] / total, 3) for w in top}

